function sourcePanel(){
  const source=sourceCatalog?.sources.find(s=>s.id===state.schedule?.importMeta.source?.id);
  const checked=source?.checkedAt||state.schedule?.importMeta.source?.checkedAt;
  const label=state.schedule?.importMeta.source?.label;
  return `<div class="source-status"><strong>${esc(label||'Источник ещё не выбран')}</strong><p>${esc(sourceMessage||(label?'Проверка при подключении к сети':'Автоматически находить и проверять книгу МФТИ'))}</p>${checked?'<small>МФТИ проверен: '+new Date(checked).toLocaleString('ru-RU')+'</small>':''}${updateCandidate?'<p>'+updateCount+' изменений в расписании группы</p><button class="primary full" data-action="review-update">Просмотреть изменения</button>':''}<button class="secondary" data-action="catalog">Выбрать программу / курс</button>${label?'<button class="subtle" data-action="check-source">Проверить обновления</button>':''}</div>`;
}
async function showCatalog(){
  try{sourceCatalog=await loadCatalog(sourceBase);}
  catch(e){toast(e.message);if(!sourceCatalog)return;}
  modal('Расписание МФТИ',`<p>Выберите программу и курс. После загрузки проверим группу и изменения.</p><div class="catalog-list">${sortSources(sourceCatalog.sources).map(s=>`<button class="catalog-item" data-source="${s.id}" ${s.status!=='ok'?'disabled':''}><strong>${esc(s.label)}</strong><small>${esc(s.academicYear)} · ${s.term==='autumn'?'Осень':'Весна'}${s.school?' · '+esc(s.school):''}</small><small>${s.status!=='ok'?'Источник временно недоступен':'Открыть и выбрать группу'}</small></button>`).join('')}</div>`);
  dialog.querySelectorAll('[data-source]').forEach(button=>button.onclick=async()=>{button.disabled=true;try{draftOverrides={};reviewChoices=new Map();candidate=await sourceCandidate(sourceCatalog.sources.find(s=>s.id===button.dataset.source),sourceBase,state);reviewImport();}catch(e){button.disabled=false;toast(e.message);}});
}
async function checkSource(manual=false){
  if(!state.schedule?.importMeta.source)return;
  try{
    sourceCatalog=await loadCatalog(sourceBase);const source=sourceCatalog.sources.find(s=>s.id===state.schedule.importMeta.source.id),status=sourceState(state.schedule,source);
    if(status==='current'){updateCandidate=null;sourceMessage='✓ Актуально по последней проверке МФТИ';}
    else if(status==='update'){updateCandidate=await sourceCandidate(source,sourceBase,state);updateCount=importDiff(state.schedule,selectedUpdate(updateCandidate,state)).filter(d=>d.type!=='unchanged').length;sourceMessage='Доступна новая версия книги';}
    else sourceMessage=status==='missing'?'Источник исчез из каталога. Текущее расписание сохранено.':'Не удалось проверить МФТИ. Текущее расписание сохранено.';
  }catch(e){sourceMessage='Нет связи с каталогом. Сохранённое расписание доступно.';}
  if(!dialog.open)render();if(manual)toast(sourceMessage);
}
function notificationPanel(){const n=state.notifications;return `<section class="settings-panel"><h2>Уведомления</h2><p>${esc(notificationStatus())}</p><button class="secondary" data-action="notification-permission">Разрешить уведомления</button>${native?'<button class="subtle" data-action="exact-settings">Точное время на Android</button>':''}<form id="notification-form">${[['enabled','Включены'],['lessons','Перед занятиями'],['sessions','Перед запланированной работой над задачей'],['followups','Один итог после занятий']].map(([k,l])=>`<label class="rule-row"><input type="checkbox" name="${k}" ${n[k]?'checked':''}>${l}</label>`).join('')}<div class="form-row"><label>До занятия, мин<input name="lessonLead" type="number" min="0" max="60" value="${n.lessonLead}" required></label><label>До работы над задачей, мин<input name="sessionLead" type="number" min="0" max="60" value="${n.sessionLead}" required></label></div><div class="form-row"><label>Тишина с<input name="quietStart" type="time" value="${clock(n.quietStart)}" required></label><label>До<input name="quietEnd" type="time" value="${clock(n.quietEnd)}" required></label></div><button class="secondary">Сохранить уведомления</button></form><p class="section-caption">${native?'Напоминания планируются системой на 30 дней вперёд и обновляются при открытии. После принудительной остановки приложения откройте Сетку снова.':'При закрытой PWA фоновые напоминания не гарантируются. Сервер Web Push не подключён; на Android используйте APK для фоновых уведомлений.'}</p></section>`;}
checkSource();
