function lessonPatch(s){return structuredClone(Object.fromEntries(['title','kind','location','instructors','cohorts','recurrence','time','hidden','semanticKey'].filter(k=>s[k]!==undefined).map(k=>[k,s[k]])));}
function welcome(preferences=false){
  if(!preferences){modal('Добро пожаловать в Сетку.',`<img class="welcome-logo" src="./assets/icon.svg" width="64" height="64" alt=""><p>Узнайте, какая пара сейчас, что дальше и что успеете между занятиями. Расписание, личные события и задачи работают офлайн.</p><ol class="welcome-steps"><li>Выберите книгу МФТИ и свою группу.</li><li>Проверьте занятия, варианты и семестр.</li><li>Настройте задачи после занятий и напоминания.</li></ol><button class="primary full" data-action="catalog">Выбрать расписание МФТИ</button><label class="file-button secondary">Открыть свой XLS / XLSX<input id="xlsx-file" type="file" accept=".xls,.xlsx"></label><button class="text-link" data-action="setup-preferences">${state.schedule?'Настроить предпочтения':'Пока без расписания'} →</button>`);return;}
  modal('Подстроим Сетку под вас',`<form id="setup-form"><p class="section-caption">После занятия можно автоматически создать задачу. Время — только начальная оценка. Обычные занятия и неизвестные типы не создают домашнюю работу по умолчанию.</p>${state.rules.map(r=>`<div class="setup-rule"><label class="checkbox-label"><input type="checkbox" name="rule" value="${esc(r.id)}" ${r.enabled?'checked':''}>${esc(kinds[r.kind])} · ${esc(r.title)}</label><label>Примерно, мин<input type="number" name="minutes-${esc(r.id)}" min="5" max="600" value="${r.minutes}" required></label></div>`).join('')}<div class="form-row"><label>Планировать с<input name="start" type="time" required value="${clock(state.settings.dayStart)}"></label><label>До<input name="end" type="time" required value="${clock(state.settings.dayEnd)}"></label></div><p class="section-caption">Обед, спорт и другие повторяющиеся личные блоки добавляются через «＋ Событие».</p><label class="checkbox-label"><input name="reminders" type="checkbox" ${state.notifications.enabled?'checked':''}>Включить напоминания о занятиях и запланированных задачах</label><div class="form-row"><label>До занятия, мин<input name="lead" type="number" min="0" max="60" value="${state.notifications.lessonLead}" required></label><label>До работы над задачей, мин<input name="workLead" type="number" min="0" max="60" value="${state.notifications.sessionLead}" required></label></div><p class="section-caption">Тихие часы: ${clock(state.notifications.quietStart)}–${clock(state.notifications.quietEnd)}. Остальные настройки доступны в «Ещё».</p><label class="checkbox-label"><input name="past" type="checkbox" ${state.schedule?'':'disabled'}>Выбрать задачи за последние 7 дней</label><button class="primary full">Начать пользоваться</button></form>`);
}
function catchupPreview(){const proposed=previousWeekTasks(state,now());modal('Задачи за последние 7 дней',`<p>Только завершившиеся занятия по включённым правилам. Не больше 30 задач за один просмотр; уже созданные не повторяются.</p><form id="catchup-form">${proposed.map(t=>`<label class="checkbox-label"><input name="task" value="${esc(t.id)}" type="checkbox" checked><span>${esc(t.title)}<small> · ${formatDate(t.origin.date)} · ≈ ${duration(t.remainingMinutes)}</small></span></label>`).join('')||'<p>Новых задач нет. Проверьте расписание и правила.</p>'}<button class="primary full" ${proposed.length?'':'disabled'}>Добавить выбранные задачи (${proposed.length})</button></form>`);dialog.querySelector('#catchup-form').onsubmit=e=>{e.preventDefault();const ids=new Set(new FormData(e.target).getAll('task'));mutate(()=>{for(const t of proposed)if(ids.has(t.id)&&!state.generatedKeys.includes(t.id)){state.tasks.push(t);state.generatedKeys.push(t.id);}dialog.close();toast('Выбранные задачи добавлены');});};}
function correctionForm(s,fromImport=false,unresolved=false){
  editingLesson={s:structuredClone(s),fromImport,unresolved};
  modal('Уточнить занятие',`<p>Изменения сохраняются отдельно от исходного текста. Для двух вариантов сохраните первый, затем нажмите «Добавить вариант».</p><blockquote class="correction-source">${esc(s.source.rawText)}</blockquote><form id="correction-form"><label>Название<input name="title" required maxlength="180" value="${esc(s.title||'')}"></label><div class="form-row"><label>Тип<select name="kind">${Object.entries(kinds).filter(([k])=>k!=='work').map(([k,l])=>`<option value="${k}" ${s.kind===k?'selected':''}>${l}</option>`).join('')}</select></label><label>День недели<select name="weekday">${shortDays.map((d,i)=>`<option value="${i+1}" ${s.recurrence?.weekdays?.[0]===i+1?'selected':''}>${d}</option>`).join('')}</select></label></div><label>Повторение<select name="parity">${[['all','Каждую неделю'],['odd','Нечётные недели'],['even','Чётные недели'],['date','Только в указанную дату']].map(([k,l])=>`<option value="${k}" ${(s.recurrence?.datesOnly?'date':s.recurrence?.parity)===k?'selected':''}>${l}</option>`).join('')}</select></label><label>Дата для разового занятия<input name="date" type="date" value="${s.recurrence?.includeDates?.[0]||''}"></label><div class="form-row"><label>Начало<input name="start" type="time" required value="${s.time?.startsAt||''}"></label><label>Конец<input name="end" type="time" required value="${s.time?.endsAt||''}"></label></div><label>Место<input name="location" maxlength="180" value="${esc(s.location||'')}"></label><label>Преподаватели (через запятую)<input name="instructors" maxlength="500" value="${esc(s.instructors?.join(', ')||'')}"></label><button class="primary full">Сохранить уточнение</button>${!unresolved?'<button type="submit" name="variant" value="yes" class="secondary full">Добавить вариант</button>':''}</form>`);
}
document.addEventListener('click',e=>{
  const b=e.target.closest('button');if(!b)return;const a=b.dataset.action,id=b.dataset.id;
  if(a==='welcome')welcome();if(a==='setup-preferences')welcome(true);if(a==='catchup-preview')catchupPreview();
  if(a==='correct-import')correctionForm(candidate.series.find(s=>s.id===id),true);
  if(a==='edit-lesson')correctionForm(state.schedule.series.find(s=>s.id===id));
  if(a==='correct-unresolved'){const u=candidate.importMeta.unresolved.find(u=>u.range===id);correctionForm({id:`unresolved:${u.sheet}:${u.range}`,source:{fingerprint:`unresolved:${u.sheet}:${u.range}`,sheet:u.sheet,ranges:[u.range],rawText:u.rawText,workbook:candidate.importMeta.workbook},kind:'other'},true,true);}
  if(a==='hide-lesson'||a==='restore-lesson')mutate(()=>{const s=state.schedule.series.find(s=>s.id===id);s.hidden=a==='hide-lesson';state.overrides[s.source.fingerprint]={workbook:s.source.workbook,rawText:s.source.rawText,replacements:state.schedule.series.filter(x=>x.source.fingerprint===s.source.fingerprint).map(lessonPatch)};dialog.close();toast(s.hidden?'Занятие скрыто. Вернуть можно в «Ещё».':'Занятие возвращено');});
  if(a==='hidden-lessons')modal('Убранные из моего расписания занятия',`<p>Вы сами убрали эти занятия из показа. Они сохранены вместе с источником и могут быть возвращены.</p>${(state.schedule?.series||[]).filter(s=>s.hidden).map(s=>`<p>${esc(s.title)} <button class="secondary" data-action="restore-lesson" data-id="${esc(s.id)}">Вернуть</button></p>`).join('')||'<p>Нет скрытых занятий.</p>'}`);
  if(a==='add-rule')modal('Своё правило',`<form id="custom-rule-form"><label>Для какого типа<select name="kind">${['lecture','seminar','lab','practice','class'].map(k=>`<option value="${k}">${kinds[k]}</option>`).join('')}</select></label><label>Что сделать<input name="title" required maxlength="100"></label><label>Примерно, мин<input name="minutes" type="number" required min="5" max="600" value="30"></label><p class="section-caption">Для каждого типа действует одно правило. Существующее правило этого типа будет обновлено.</p><button class="primary full">Сохранить правило</button></form>`);
});
document.addEventListener('submit',async e=>{
  const f=e.target,v=new FormData(f);
  if(f.id==='setup-form'){
    const start=minute(v.get('start')),end=minute(v.get('end'));if(end<=start){toast('Конец дня должен быть позже начала.');return;}
    let granted=false;if(v.has('reminders')){try{granted=await permission(true)==='granted';}catch{toast('Разрешение недоступно. Его можно включить позже.');}}
    mutate(()=>{catchUp(state,now());state.rules.forEach(r=>{r.enabled=v.getAll('rule').includes(r.id);r.minutes=Number(v.get('minutes-'+r.id));});Object.assign(state.settings,{dayStart:start,dayEnd:end,onboarded:true});Object.assign(state.notifications,{enabled:granted,lessonLead:Number(v.get('lead')),sessionLead:Number(v.get('workLead'))});view='today';date=now().date;dialog.close();});if(v.has('past'))catchupPreview();
  }
  if(f.id==='custom-rule-form')mutate(()=>{catchUp(state,now());const kind=v.get('kind'),existing=state.rules.find(r=>r.kind===kind);const fields={kind,title:v.get('title').trim(),minutes:Number(v.get('minutes')),enabled:true};if(!fields.title)throw Error('Введите название.');if(existing)Object.assign(existing,fields);else state.rules.push({id:'custom-'+kind,...fields});dialog.close();});
  if(f.id==='correction-form'){
    try{
      const {s,fromImport,unresolved}=editingLesson,sc=fromImport?candidate:state.schedule;
      const start=v.get('start'),end=v.get('end'),parity=v.get('parity'),d=v.get('date');
      if(minute(start)>=minute(end)||!v.get('title').trim())throw Error('Проверьте название и время.');
      if(parity==='date'&&(!validDate(d)||d<sc.term.startsOn||d>sc.term.endsOn))throw Error('Выберите дату в семестре.');
      const patch={...lessonPatch(s),title:v.get('title').trim(),kind:v.get('kind'),location:v.get('location').trim(),instructors:v.get('instructors').split(',').map(x=>x.trim()).filter(Boolean),cohorts:s.cohorts||[{groupId:reviewGroup||state.groupId}],recurrence:{weekdays:[Number(v.get('weekday'))],parity:parity==='date'?'all':parity,validFrom:sc.term.startsOn,validTo:sc.term.endsOn,...(parity==='date'?{datesOnly:true,includeDates:[d]}:{})},time:{startsAt:start,endsAt:end,slotNumbers:sc.bellSchedule.slots.filter(b=>minute(b.startsAt)<minute(end)&&minute(b.endsAt)>minute(start)).map(b=>b.number)}};
      const siblings=sc.series.filter(x=>x.source.fingerprint===s.source.fingerprint),patches=siblings.map(lessonPatch),index=siblings.findIndex(x=>x.id===s.id);
      if(e.submitter?.name==='variant')patches.push(patch);else if(index>=0)patches[index]=patch;else patches.push(patch);
      const override={workbook:s.source.workbook,rawText:s.source.rawText,replacements:patches};
      if(fromImport){draftOverrides[s.source.fingerprint]=override;candidate=applyOverrides(candidate,{[s.source.fingerprint]:override});reviewImport(reviewGroup);}
      else mutate(()=>{catchUp(state,now());state.overrides[s.source.fingerprint]=override;state.schedule=applyOverrides(state.schedule,{[s.source.fingerprint]:override});dialog.close();});
    }catch(error){toast(error.message);}
  }
});

function taskDetail(id){const t=state.tasks.find(t=>t.id===id);if(!t)return;modal(t.title,`<p>${t.status==='done'?'Выполнена':'В работе'} · примерно ${duration(t.remainingMinutes)} работы</p><p>${t.dueOn?'Завершить до '+formatDate(t.dueOn):'Без срока'} · приоритет ${t.priority}/5</p>${t.notes?'<p class="task-notes">'+esc(t.notes)+'</p>':''}${t.origin?'<p>После занятия: '+esc(t.origin.subject)+' · '+formatDate(t.origin.date)+'</p>':''}<div class="primary-actions">${t.status==='todo'?'<button class="primary" data-action="edit-task" data-id="'+esc(id)+'">Изменить задачу</button><button class="secondary" data-action="manual-plan" data-id="'+esc(id)+'">Запланировать</button>':'<button class="primary" data-action="complete-task" data-id="'+esc(id)+'">Вернуть в работу</button>'}</div>`);}

