async function expandWeek(){
 if(!weekExpanded)expandedZoomState={};
 if(!weekExpanded)weekBeforeExpand={zoom:weekZoom,scrollX:window.scrollX,scrollY:window.scrollY,gridLeft:document.querySelector('.grid-scroll')?.scrollLeft||0};
 weekExpanded=!weekExpanded;if(!weekExpanded&&weekBeforeExpand)weekZoom=weekBeforeExpand.zoom;expandedMobile=weekExpanded&&(native||matchMedia('(max-width:650px), (pointer:coarse)').matches);render();if(weekExpanded)window.scrollTo(0,0);else{document.querySelector('.grid-scroll')?.scrollTo(weekBeforeExpand?.gridLeft||0,0);window.scrollTo(weekBeforeExpand?.scrollX||0,weekBeforeExpand?.scrollY||0);}
 if(native){try{await window.Capacitor.Plugins.SetkaExport.weekOrientation({expanded:weekExpanded});}catch(e){toast('Не удалось изменить ориентацию: '+e.message);}return;}
 if(expandedMobile){try{await document.documentElement.requestFullscreen();await screen.orientation.lock('landscape');}catch{toast('Если браузер не повернул экран, поверните телефон горизонтально.');}}
 else {screen.orientation?.unlock?.();if(document.fullscreenElement)await document.exitFullscreen();}
}
